-- Family food inventory: the actual product now. One table, no event
-- sourcing, no reconciliation engine — just what's in the house.
--
-- Seeded once from the 250 real items previously tracked in Airtable
-- (migrated 2026-10-01). `location` was inferred from free-text notes
-- where possible; items with no location clue land in 'Unsorted' and can
-- be re-tagged from the app. Items whose notes said "Freezer 2" are the
-- outside/garage freezer specifically — note the 2026-10-01 household
-- notes signal these are the easy-to-forget freezer.

CREATE TABLE IF NOT EXISTS family_inventory (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  quantity REAL,
  unit TEXT,
  location TEXT NOT NULL DEFAULT 'Unsorted',
  status TEXT,
  notes TEXT,
  added_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_family_inventory_location ON family_inventory(location);

